mapper.insert:

    SELECT
        'APAS'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(APPLICANT_ANSWER_NO), LENGTH('APAS' ) + 1)), 0) + 1, 6, '0')
    FROM APPLICANT_ANSWER

	INSERT INTO APPLICANT_ANSWER (
		APPLICANT_ANSWER_NO
		, RECRUIT_EXAM_NO
		, RECRUIT_QUESTIONS_NO
		, APPLICANT_ID
		, APPLICANT_OPTION_NO
		, APPLICANT_SCORE
	) VALUES (
		#{applicantAnswerNo}
		, #{recruitExamNo}
		, #{recruitQuestionsNo}
		, #{applicantId}
		, #{applicantOptionNo}
		, #{applicantScore}
	)

mapper.update:
UPDATE APPLICANT_ANSWER SET 
	APPLICANT_SCORE = #{applicantScore} 
WHERE APPLICANT_ANSWER_NO = #{applicantAnswerNo}

mapper.select:
SELECT COUNT(*)
  FROM APPLICANT_ANSWER
 WHERE APPLICANT_ID    = #{applicantId}
   AND RECRUIT_EXAM_NO = #{recruitExamNo}
